  legacy_id,
  name,
  muscle_group,
  primary_muscles,
  secondary_muscles,
  equipment,
  execution_steps,
  tips,
  prescription_type,
  record_type,
  is_custom,
  default_rest_seconds,
  organization_id
)
SELECT 
  gen_random_uuid(),
  'ex-sys-0227',
  'Puxada (Pulldown) Fechada',
  'Costas',
  ARRAY[]::text[],
  ARRAY['Bíceps', 'Deltóide Posterior']::text[],
  'Peso Corporal',
  ARRAY['Posicione-se adequadamente utilizando Peso Corporal.', 'Mantenha a postura alinhada, respiração controlada e core ativo.', 'Execute o movimento na cadência recomendada respeitando a biomecânica articular.', 'Finalize a repetição no ponto de partida com total controle.']::text[],
  ARRAY['Concentre a força no músculo primário sem recorrer a compensações.', 'Controle a velocidade excêntrica para otimizar hipertrofia e segurança.']::text[],
  'weight_reps',
  'weight_reps',
  false,
  90,
  NULL
WHERE NOT EXISTS (
  SELECT 1 FROM exercises WHERE legacy_id = 'ex-sys-0227' OR name = 'Puxada (Pulldown) Fechada'
);

